   733          case BPF_ADD:
   734                  a += b;
   735                  break;
   736
   737          case BPF_SUB:
   738                  a -= b;
   739                  break;
   740
   741          case BPF_MUL:
   742                  a *= b;
   743                  break;
   744
   745          case BPF_DIV:
   746                  if (b == 0)
   747                          opt_error(opt_state, "division by zero");
   748                  a /= b;
   749                  break;
   750
   751          case BPF_MOD:
   752                  if (b == 0)
   753                          opt_error(opt_state, "modulus by zero");
   754                  a %= b;
   755                  break;
   756
   757          case BPF_AND:
   758                  a &= b;
   759                  break;
